using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using TechnifyERP.Application.Website;
namespace TechnifyERP.Areas.Admin;
[Area("Admin"),Authorize(Roles="SuperAdmin")]public sealed class WebsiteController(IHomepageService service):Controller{public async Task<IActionResult>Index(CancellationToken ct)=>View(await service.GetAsync(ct));[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>Save(HomepageContentDto content,CancellationToken ct){await service.SaveAsync(content,ct);TempData["SuccessMessage"]="Homepage content save ho gaya.";return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult>SaveSections(List<HomepageStatDto> stats,List<HomepageFeatureDto> features,CancellationToken ct){await service.SaveSectionsAsync(stats,features,ct);TempData["SuccessMessage"]="Homepage stats aur feature cards save ho gaye.";return RedirectToAction(nameof(Index));}}
